  payment_year_2_paid boolean DEFAULT false,
  payment_year_3_paid boolean DEFAULT false,
  member_status text DEFAULT 'active'::text,
  resigned_at timestamp with time zone,
  redistributed_to jsonb
);

CREATE TABLE public.incentive_projects (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  reminder_id uuid,
  project_name text NOT NULL,
  category text NOT NULL,
  sales_name text,
  sales_division text,
  due_date date,
  handler_name text NOT NULL,
  handler_username text,
  backup_names text[] DEFAULT '{}'::text[],
  biaya_cadangan numeric(15,2) DEFAULT 0,
  biaya_input_by text,
  biaya_input_at timestamp with time zone,
  periode text,
  status text DEFAULT 'pending'::text,
  paid_at timestamp with time zone,
