  description text,
  notes text,
  pic_name text,
  pic_phone text,
  product text,
  supervisor_name text,
  installer_paid boolean DEFAULT false
);

-- Sumber tunggal skema pembagian insentif PTS (Scheme Setting). Setiap Simpan
-- menambah baris BARU (riwayat versi) - ambilSkema() selalu membaca baris
-- ber-updated_at TERBARU. Lihat lib/incentive-scheme.ts.
CREATE TABLE public.incentive_scheme_settings (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  scheme jsonb NOT NULL,
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_by text
);

-- Skema LAMA handler/backup (dipakai incentive_disbursements). Dipertahankan
-- untuk kompatibilitas riwayat, bukan sumber skema yang aktif dipakai layar
-- Incentive PTS saat ini (lihat incentive_scheme_settings).
CREATE TABLE public.incentive_settings (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  handler_pct numeric(5,2) NOT NULL DEFAULT 70.00,
  backup_pct numeric(5,2) NOT NULL DEFAULT 30.00,
  updated_by text,
  updated_at timestamp with time zone DEFAULT now(),
  pts_supervisor_username text,
  pts_manager_username text
);

-- Pembagian NOMINAL per orang per tahapan (hasil Process Batch). project_id
-- merujuk reminders.id (BUKAN incentive_projects.id) - lihat incentive_tranches.
CREATE TABLE public.incentive_splits (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  project_id uuid NOT NULL,
  tranche_id uuid,
  role text NOT NULL,
  user_id uuid,
  user_name text,
  percentage numeric NOT NULL,
  amount numeric,
  source_ticket_id uuid,
  created_at timestamp with time zone DEFAULT now()
);

-- Tahapan pencairan (T1/T2/T3) satu project. project_id merujuk reminders.id.
-- scheme_snapshot MEMBEKUKAN skema yang berlaku saat tahapan dibuat, supaya
-- perubahan skema di kemudian hari tidak mengubah tahapan yang sudah ada.
CREATE TABLE public.incentive_tranches (
