  id uuid NOT NULL DEFAULT gen_random_uuid(),
  project_name text NOT NULL,
  description text DEFAULT ''::text,
  assigned_to text NOT NULL,
  assign_name text NOT NULL,
  due_date date NOT NULL,
  due_time time without time zone DEFAULT '09:00:00'::time without time zone,
  priority text DEFAULT 'medium'::text,
  status text DEFAULT 'pending'::text,
  repeat text DEFAULT 'none'::text,
  category text DEFAULT 'Umum'::text,
  created_by text NOT NULL,
  created_at timestamp with time zone DEFAULT now(),
  notes text DEFAULT ''::text,
  sales_name text DEFAULT ''::text,
  address text DEFAULT ''::text,
  pic_name text,
  pic_phone text,
  completion_photo_url text,
  sales_division text,
  product text,
  guest_fullname text,
  warranty_years smallint,
  updated_at timestamp with time zone DEFAULT now(),
  is_deleted boolean DEFAULT false,
  deleted_by text,
  deleted_at timestamp with time zone,
  mode_penyelesaian character varying(10),
  installer_name text,
  installer_daerah text,
  requires_controller_automation boolean DEFAULT false,
  controller_automation_brand text,
  pic_type text DEFAULT 'standard'::text,
  pic_id uuid,
  domain_owner text,
  bast_date date,
  incentive_value numeric DEFAULT 0,
  display_type text,
  requires_middleware boolean DEFAULT false,
  execution_mode text,
  product_type text,
  batch_id uuid,
  routing_status text,
  internal_sales_id uuid,
  internal_approved_by uuid,
  internal_approved_at timestamp with time zone,
  rejection_reason text,
  assigned_supervisor_id uuid,
  brand text,
  internal_sales_id_2 uuid,
  internal_approved_at_2 timestamp with time zone,
  progress_start_date date,
  progress_target_date date,
  sales_user_id uuid,
  assign_user_id uuid,
  incentive_tarif_kunci text,
  incentive_dasar_hpp numeric,
  incentive_excluded boolean DEFAULT false,
  incentive_group_id uuid
);

-- Pelacak SQL yang sudah dijalankan manual (sql/ folder) - dokumentasi, bukan
-- migration runner otomatis. Boleh dikosongkan di instalasi baru.
CREATE TABLE public.sql_diterapkan (
  berkas text NOT NULL,
  urutan integer NOT NULL,
  golongan text NOT NULL,
  diterapkan_pada timestamp with time zone,
  catatan text
);

CREATE TABLE public.team_members (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  name text NOT NULL,
  username text,
  photo_url text,
  role text,
  created_at timestamp without time zone DEFAULT now(),
  team_type text
);

CREATE TABLE public.tech_note_folders (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
