);

-- Tabel INTI - akun aplikasi (bukan auth.users Supabase - login custom lewat
-- user_credentials/user_sessions). role/team_type/allow_incentive_input/
-- allowed_menus/access_level DIJAGA trigger guard_users_privileged_columns
-- (lihat 05_functions_triggers.sql) - hanya bisa diubah lewat service_role
-- (server-side), bukan langsung dari klien.
CREATE TABLE public.users (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  username text NOT NULL,
  role text DEFAULT 'team'::text,
  full_name text NOT NULL,
  created_at timestamp without time zone DEFAULT now(),
  team_type text,
  phone_number text,
  allowed_menus text[] DEFAULT ARRAY['form-bast'::text, 'ticket-troubleshooting'::text, 'daily-report'::text, 'database-pts'::text, 'unit-movement'::text],
  sales_division text,
  jabatan text,
  kpi_enabled boolean NOT NULL DEFAULT true,
  allow_incentive_input boolean DEFAULT false,
  divisi character varying(50),
  pts_type character varying(50),
  atasan_id uuid,
  is_internal_sales boolean NOT NULL DEFAULT false,
  access_level text NOT NULL DEFAULT 'guest'::text,
  incentive_brand_scope text
);
